/* The typings of @filen/sdk-rs's Node-API addon, generated by NAPI-RS (napi build) below this
 * header. They match what uniffi-bindgen-react-native generates for the same items, so code
 * written against the react-native build type-checks against this one.
 *
 * Load the addon in one Node environment per process: the Electron main process or a
 * utilityProcess, not renderers or worker_threads. The SDK's runtime and napi's are shared
 * by every environment in the process.
 *
 * A JS value of the wrong type for an argument (a number where a bigint belongs, a missing
 * required key, an asyncOpts_ whose signal is not an AbortSignal) throws napi's own error
 * synchronously, also from a method that returns a
 * Promise, where ubrn's async methods reject. So does a cache listener without an onMessages
 * method, a sync engine listener without onEvents and onWatchStatus methods, and a transfer
 * callback without one of its methods (onUpdate, the six of a JsDirDownloadCallback, the five
 * of a JsDirUploadCallback, or a listing's onProgress or onErrors). Every
 * SDK error of an async call rejects, as under ubrn, and so
 * does a managedFuture whose abortSignal or pauseSignal is null or of another class (a
 * Conversion error).
 *
 * Listener methods are called as methods of the listener (`this` is bound to it), on the JS
 * thread, in the order their deliveries happened. They are read once, when the listener is
 * handed over (configureCache, openSyncEngine), so replacing them on the object later has no
 * effect. A sync engine listener method that throws is logged, and the rest of its chunk is
 * still delivered. After an attach replaces an engine's listener, the old one may still get the
 * rest of the delivery round in progress: the chunks already handed to the JS thread (up to two
 * queued and the one being delivered) and those of that round not yet handed over. The next round
 * goes to the new listener.
 *
 * A transfer's callback object (downloadFileToPath, uploadFile, downloadDirRecursively,
 * uploadDirRecursively, and listDirRecursiveWithPaths' two) is read
 * once, when the call is made, and its methods are called bound to it, on the JS thread, in order.
 * Every call made before the transfer settles runs before its promise settles, except after an
 * abort. One through asyncOpts_ rejects at once; one through the managedFuture's
 * ManagedAbortSignal rejects as soon as the transfer is told to stop, which may still make a call
 * and remove its temp files just after. Either way, calls already queued or made while it stops
 * may arrive after the rejection.
 *
 * Sync engine listener calls and promise settlement are not ordered against each other: syncOnce, stopWatch
 * or close may resolve before the listener gets that call's last events or status. A UI reads
 * where a pair stands from listPairs, lastReport and a watch's status, not from arrival order.
 *
 * A sync engine belongs to the Node environment that opened it, one environment per engine: an
 * open of its baseline from another environment of the process is refused with BaselineInUse,
 * where one from the same environment and account attaches. An engine closes with its
 * environment: when that goes away (process exit, a worker ending, a reload), its teardown closes
 * every engine it opened that is still open, waiting up to 5 s for them; one still closing after
 * that keeps its baseline until it has. Closing an engine explicitly is still how to wait for it.
 *
 * An rclone daemon (startRcloneDaemon) belongs to the Node environment that started it in the
 * same way: its teardown stops every daemon it started that still runs (serves stopped, drives
 * unmounted, rclone asked to quit and killed after 3 s), waiting up to 5 s, and rclone's watchdog
 * stops one that outlasts that. A JsRcloneDaemon that is garbage-collected kills its rclone; stop
 * is how to stop it gracefully.
 *
 * napi has no ManagedFuture.create: a managed call takes a plain object, whose abortSignal and
 * pauseSignal are a ManagedAbortSignal and a PauseSignal or undefined.
 *
 * Bytes cross as a Uint8Array where ubrn has an ArrayBuffer: napi has no owned ArrayBuffer.
 *
 * A data enum (AnyFile, ParentUuid, FileMeta and the rest) is a plain { tag, inner } object,
 * not an instance of a class as ubrn's are: build one as an object literal, its tag taken from
 * the enum's X_Tags (ParentUuid_Tags.Uuid), and tell one apart by its tag. A variant without a
 * payload has no inner.
 *
 * This header declares what napi cannot generate from Rust. */
/* eslint-disable */

/** An `Error` carrying the SDK object it was thrown for, as ubrn throws it. */
export interface UniffiThrownObject<T> extends Error {
	readonly inner: T
}

export type JsClientInterface = JsClient
export type UnauthJsClientInterface = UnauthJsClient
export type FilenSdkErrorInterface = FilenSdkError
export type JsSyncEngineInterface = JsSyncEngine
export type JsSyncPlanInterface = JsSyncPlan
export type JsSyncWatchInterface = JsSyncWatch
export type JsRcloneDaemonInterface = JsRcloneDaemon
export type PauseSignalInterface = PauseSignal
export type ManagedAbortControllerInterface = ManagedAbortController
export type ManagedAbortSignalInterface = ManagedAbortSignal

/** A BLAKE3 hash, 32 bytes. */
export type Blake3Hash = Uint8Array

/** The milliseconds since the epoch, as uniffi lowers a date. */
export type DateTime = bigint
export type Uuid = string
export type UuidStr = string
export type StableUuid = string
export type LinkPasswordSalt = string
export type LinkHashedPasswordStatic = string
export type MaybeEncryptedStatic = MaybeEncryptedUniffi

/** What a managed call can be paused and aborted through. */
export type ManagedFuture = {
	abortSignal: ManagedAbortSignalInterface | undefined
	pauseSignal: PauseSignalInterface | undefined
}

/**
 * Receives every status-message batch the cache worker emits (see [`CacheStatusMessage`]).
 * Registered ONCE via [`JsClient::configure_cache`] and reused across worker restarts.
 */
export interface CacheStatusListener {
	onMessages(messages: Array<CacheStatusMessage>): void
}

/**
 * Receives every pair's pass events and watch statuses, in the order they happened. Must return
 * quickly: deliveries wait while it runs.
 */
export interface SyncEngineListener {
	/** A run of consecutive pass events, at most 512. */
	onEvents(events: Array<SyncPassEvent>): void
	/** A watch's status changed (and once when the watch starts). */
	onWatchStatus(pairId: bigint, status: WatchStatus): void
}

/** Receives a file download's progress. */
export interface JsFileDownloadCallback {
	/**
	 * `downloadedBytes` is a **delta**: the plaintext bytes downloaded since the previous call,
	 * not a running total. Their sum is the file's size once the download completes.
	 */
	onUpdate(downloadedBytes: bigint): void
}

/** Receives a file upload's progress. */
export interface JsFileUploadCallback {
	/**
	 * `uploadedBytes` is a **delta**: the plaintext bytes uploaded since the previous call, not a
	 * running total. Their sum is the file's size once the upload completes.
	 */
	onUpdate(uploadedBytes: bigint): void
}

/** Receives a directory download's progress. */
export interface JsDirDownloadCallback {
	/** Called periodically while /dir/download is listing the directory contents. */
	onQueryDownloadProgress(knownBytes: bigint, totalBytes: bigint | undefined): void
	/** Called during tree building. */
	onScanProgress(knownDirs: bigint, knownFiles: bigint, knownBytes: bigint): void
	/** Called when errors occur during tree building. */
	onScanErrors(errors: Array<FilenSdkErrorInterface>): void
	/** Called when tree building is complete. */
	onScanComplete(totalDirs: bigint, totalFiles: bigint, totalBytes: bigint): void
	/** Called periodically during the download process. */
	onDownloadUpdate(downloadedDirs: Array<DirWithPath>, downloadedFiles: Array<FileWithPath>, downloadedBytes: bigint): void
	/** Called when errors occur during the download process. */
	onDownloadErrors(errors: Array<DownloadError>): void
}

/** Receives a directory upload's progress. */
export interface JsDirUploadCallback {
	/** Called during tree building. */
	onScanProgress(knownDirs: bigint, knownFiles: bigint, knownBytes: bigint): void
	/** Called when errors occur during tree building. */
	onScanErrors(errors: Array<FilenSdkErrorInterface>): void
	/** Called when tree building is complete. */
	onScanComplete(totalDirs: bigint, totalFiles: bigint, totalBytes: bigint): void
	/** Called periodically during the upload process, with what was uploaded since its last call. */
	onUploadUpdate(uploadedDirs: Array<Dir>, uploadedFiles: Array<File>, uploadedBytes: bigint): void
	/** Called when errors occur during the upload process, each with the local path that failed. */
	onUploadErrors(errors: Array<UploadError>): void
}

/** Receives a recursive listing's download progress (listDirRecursiveWithPaths). */
export interface DirContentDownloadProgressCallback {
	/** The bytes of the listing downloaded so far, and its total once known. */
	onProgress(bytesDownloaded: bigint, totalBytes: bigint | undefined): void
}

/** Receives the errors a recursive listing meets reading its entries (listDirRecursiveWithPaths). */
export interface DirContentDownloadErrorCallback {
	onErrors(errors: Array<FilenSdkErrorInterface>): void
}
